bool overlaps(const RiverLine& a,const RiverLine& b,float extend){float ea=std::clamp(extend/a.length,0.0f,1.0f),eb=std::clamp(extend/b.length,0.0f,1.0f);return intersect(a.a-a.delta*ea,a.b+a.delta*ea,b.a-b.delta*eb,b.b+b.delta*eb);}
